card.display:
[[[
  var zone = '10';
  if (states['input_select.irrigation_cycle'].state != 'cycle3')
    return 'none';
  else if (states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
          states['input_boolean.irrigation_cycle2_running'].state == 'on')
    return 'none';
  else if (
          entity.state == 'on' &&
          states['timer.irrigation_zone' + zone + '_timer'].state != 'active'
          )
    return 'none';
  else return '';
]]]

card.border:
[[[
  var zone = '10';
  if (entity.state == 'on' &&
      states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle2_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle3_running'].state == 'on')
    return ''; 
  else return '1px solid var(--accent-color)';
]]]

card.padding:
[[[
  var zone = '10';
  if (entity.state == 'on' ||
      states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle2_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle3_running'].state == 'on')
    return '0em';
  else return '0.5em';
]]]

icon.color:
[[[
  var zone = '10';
  if (entity.state === 'on' &&
      states['timer.irrigation_zone' + zone + '_timer']?.state === 'active')
    return 'red';
  return states['input_boolean.irrigation_master_control_switch']?.state === 'on' &&
         states['input_boolean.irrigation_stop_in_progress']?.state === 'off' &&
         entity.state === 'off' &&
         [1, 2, 3].every(c => states['input_boolean.irrigation_cycle' + c + '_running']?.state === 'off')
    ? 'green' : 'var(--disabled-text-color)';
]]]

tap_action.action:
[[[
  if (entity.state === 'on' &&
      states['timer.irrigation_zone10_timer']?.state === 'active')
    return 'call-service';
  return states['input_boolean.irrigation_master_control_switch']?.state === 'on' &&
         states['input_boolean.irrigation_stop_in_progress']?.state === 'off' &&
         entity.state === 'off' &&
         [1, 2, 3].every(c => states['input_boolean.irrigation_cycle' + c + '_running']?.state === 'off')
    ? 'call-service' : 'none';
]]]

tap_action.service:
[[[
  var zone = '10';
  if (entity.state == 'off' &&
      states['input_boolean.irrigation_cycle1_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle2_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle3_running'].state == 'off')
    return 'script.irrigation_run_a_single_zone_on_demand';
  else if (entity.state == 'on' &&
            states['timer.irrigation_zone' + zone + '_timer'].state == 'active')
    return 'script.irrigation_cancel_irrigation';
  else return '';
]]]

row.content:
{% set cycle =  2  %} {% set zone =  10  %} {%
  if cycle | int != 3 and
      (
        states('input_boolean.irrigation_cycle' ~ cycle ~ '_adjust_for_rainfall') == 'on' or
        states('input_boolean.irrigation_cycle' ~ cycle ~ '_adjust_for_temperature') == 'on'
      ) 
%}
  {% set duration = states('sensor.irrigation_cycle' ~ cycle ~ '_zone' ~ zone ~ '_actual_duration_in_seconds') %}
  {% set min = ((duration | float(0)) / 60) | int %}
  {% set sec = ((((duration | float(0)) / 60) - min) * 60) | int %}
  <font color=var(--primary-text-color)><center>Czas po korekcie opadów i temperatury: {{ min }} min  {{ sec }} s</center></font>
{% endif %}

card_mod.style:
:host {

  {% set zone =  10  %}
  {% set cycle =  2  %}
  {% if is_state('input_number.irrigation_cycle' ~ cycle ~'_zone' ~ zone ~ '_duration', '0.0') %} 
    color: var(--secondary-text-color);
    opacity: 50%;
  {% endif %}

}

ha-card {
  background: none;
  overflow: visible !important;
}
#states {
  font-family: {{ states('input_text.irrigation_ui_font_family') }};
  font-size: 16px;
  padding: 0.25em 0.75em 0.25em 0.25em;
}
:host {

  {% if is_state('input_select.irrigation_cycle', 'cycle1') %}
    {% set cycle_ui = 1 %}
  {% elif is_state('input_select.irrigation_cycle', 'cycle2') %}
    {% set cycle_ui = 2 %}
  {% else %}
    {% set cycle_ui = 3 %}
  {% endif %}
  {% set zone =  10  %}
  {% set cycle =  2  %}
  {% if is_state('timer.irrigation_zone' ~ zone ~ '_timer', 'active') and 
        cycle_ui == 3 %}
    --state-icon-color: var(--paper-item-icon-active-color);
  {% endif %}

}

